INSERT INTO battle_questions
  (src_key, level, category, question_text, answer, wrong1, wrong2, wrong3, wrong4, wrong5, explanation, needs_calc, is_active)
VALUES
('eigo_lv1_001', 1, 'eigo', '朝、友だちに会ったときの「おはよう」は英語でどれ？', 'Good morning.', 'Good night.', 'Good evening.', 'Good afternoon.', 'Goodbye.', 'Thank you.', '「おはよう」は Good morning. です。morning は「朝」という意味です。', 0, 1),
('eigo_lv1_002', 1, 'eigo', '夜ねる前に、家族に「おやすみなさい」と言うときの英語はどれ？', 'Good night.', 'Good morning.', 'Good evening.', 'Good afternoon.', 'See you.', 'Hello.', 'ねる前は Good night. と言います。Good evening. は夜に会ったときの「こんばんは」です。', 0, 1),
('eigo_lv1_003', 1, 'eigo', '午後に人と会ったときの「こんにちは」に当たる英語はどれ？', 'Good afternoon.', 'Good morning.', 'Good evening.', 'Good night.', 'Goodbye.', 'See you.', 'afternoon は「午後」。午後に会ったときのあいさつは Good afternoon. です。', 0, 1),
('eigo_lv1_004', 1, 'eigo', 'Thank you. と言われたときの返事「どういたしまして」はどれ？', 'You''re welcome.', 'Thank you.', 'I''m sorry.', 'Nice to meet you.', 'See you.', 'Good job.', 'お礼を言われたら You''re welcome.（どういたしまして）と返します。', 0, 1),
('eigo_lv1_005', 1, 'eigo', '英語の Thank you. は、日本語でどんな意味？', 'ありがとう', 'ごめんなさい', 'こんにちは', 'さようなら', 'はじめまして', 'おやすみなさい', 'Thank you. は「ありがとう」。人にお礼を言うときに使います。', 0, 1),
('eigo_lv1_006', 1, 'eigo', 'はじめて会った人に言う「はじめまして」は英語でどれ？', 'Nice to meet you.', 'See you tomorrow.', 'How are you?', 'Good night.', 'Excuse me.', 'You''re welcome.', 'はじめて会った人には Nice to meet you. と言います。meet は「会う」という意味です。', 0, 1),
('eigo_lv1_007', 1, 'eigo', '友だちと別れるときに言う「またね」は英語でどれ？', 'See you.', 'Hello.', 'Nice to meet you.', 'How are you?', 'Thank you.', 'You''re welcome.', 'See you.（またね）は別れるときのあいさつです。Goodbye. も同じ場面で使えます。', 0, 1),
('eigo_lv1_008', 1, 'eigo', 'How are you?（元気ですか）と聞かれて「元気です」と答えるときはどれ？', 'I''m fine.', 'I''m sleepy.', 'I''m hungry.', 'I''m sad.', 'I''m tired.', 'I''m angry.', 'fine は「元気な」という意味。I''m fine. で「元気です」と答えられます。', 0, 1),
('eigo_lv1_009', 1, 'eigo', '「おなかがすいた」は英語でどれ？', 'I''m hungry.', 'I''m sleepy.', 'I''m happy.', 'I''m tired.', 'I''m thirsty.', 'I''m fine.', 'hungry は「おなかがすいた」。thirsty は「のどがかわいた」、tired は「つかれた」です。', 0, 1),
('eigo_lv1_010', 1, 'eigo', '英語で I''m sleepy. と言う人は、どんな気もち？', 'ねむい', 'うれしい', 'かなしい', 'おなかがすいた', 'のどがかわいた', 'おこっている', 'sleepy は「ねむい」という意味です。sleep（ねむる）とにていますね。', 0, 1),
('eigo_lv1_011', 1, 'eigo', '「うれしい」という気もちを表す英語はどれ？', 'happy', 'sad', 'angry', 'sleepy', 'hungry', 'tired', 'happy は「うれしい・幸せな」という意味。I''m happy. で「うれしいです」となります。', 0, 1),
('eigo_lv1_012', 1, 'eigo', '友だちの足をふんでしまった。あやまるときの英語はどれ？', 'I''m sorry.', 'Thank you.', 'You''re welcome.', 'Good job.', 'Nice to meet you.', 'Here you are.', 'あやまるときは I''m sorry.（ごめんなさい）と言います。', 0, 1),
('eigo_lv1_013', 1, 'eigo', '物を相手にわたすときの「はい、どうぞ」は英語でどれ？', 'Here you are.', 'Thank you.', 'I''m sorry.', 'Excuse me.', 'See you.', 'You''re welcome.', '物をわたすときは Here you are.（はい、どうぞ）。受け取った人は Thank you. と返します。', 0, 1),
('eigo_lv1_014', 1, 'eigo', '友だちが上手にできたとき、「よくできたね」とほめる英語は？', 'Good job.', 'I''m sorry.', 'Excuse me.', 'Good night.', 'See you.', 'You''re welcome.', 'Good job. は「よくできたね・よくやったね」とほめることばです。', 0, 1),
('eigo_lv1_015', 1, 'eigo', 'I''m fine, thank you. のあと、「あなたは？」と聞き返すことばは？', 'And you?', 'Me too.', 'See you.', 'Here you are.', 'Good job.', 'I''m sorry.', 'And you? は「あなたは（どうですか）？」と、相手にも聞き返すことばです。', 0, 1),
('eigo_lv1_016', 1, 'eigo', '「水をください」は Water, （　）. と言う。（　）に入るのは？', 'please', 'sorry', 'hello', 'welcome', 'goodbye', 'too', 'Water, please. で「水をください」。please をつけると、ていねいなたのみ方になります。', 0, 1),
('eigo_lv1_017', 1, 'eigo', '数の「8」は英語でどれ？', 'eight', 'seven', 'six', 'nine', 'three', 'five', '8は eight（エイト）です。six は6、seven は7、nine は9です。', 0, 1),
('eigo_lv1_018', 1, 'eigo', '英語の twelve はいくつ？', '12', '11', '20', '2', '13', '10', 'twelve は12です。11は eleven、20は twenty と言います。', 0, 1),
('eigo_lv1_019', 1, 'eigo', '数の「15」は英語でどれ？', 'fifteen', 'fifty', 'five', 'fourteen', 'sixteen', 'eleven', '15は fifteen です。fifty は50なので、まちがえないようにしましょう。', 0, 1),
('eigo_lv1_020', 1, 'eigo', '英語の twenty はいくつ？', '20', '12', '2', '22', '30', '200', 'twenty は20です。12は twelve、30は thirty です。', 0, 1),
('eigo_lv1_021', 1, 'eigo', '数の「100」は英語でどれ？', 'one hundred', 'one thousand', 'ten', 'ninety', 'ten thousand', 'one million', '100は one hundred です。one thousand は1000です。', 0, 1),
('eigo_lv1_022', 1, 'eigo', '「two たす three」の答えを英語で言うとどれ？', 'five', 'four', 'six', 'seven', 'eight', 'nine', 'two は2、three は3。2たす3は5なので five です。', 0, 1),
('eigo_lv1_023', 1, 'eigo', '英語で How many? と聞かれた。何をたずねられている？', '数（いくつ？）', '色（何色？）', '人（だれ？）', '場所（どこ？）', '時（いつ？）', '理由（なぜ？）', 'How many? は「いくつ？」と数をたずねることば。How many apples? なら「りんごはいくつ？」です。', 0, 1),
('eigo_lv1_024', 1, 'eigo', '数の「11」は英語でどれ？', 'eleven', 'twelve', 'seven', 'seventeen', 'ten', 'twenty', '11は eleven（イレブン）です。12は twelve、17は seventeen です。', 0, 1),
('eigo_lv1_025', 1, 'eigo', '英語の nine はいくつ？', '9', '5', '6', '1', '19', '90', 'nine は9です。19は nineteen、90は ninety と言います。', 0, 1),
('eigo_lv1_026', 1, 'eigo', '英語の seven はいくつ？', '7', '6', '8', '11', '17', '70', 'seven は7です。17は seventeen、70は seventy です。', 0, 1),
('eigo_lv1_027', 1, 'eigo', '「ten ひく four」の答えを英語で言うとどれ？', 'six', 'five', 'seven', 'four', 'eight', 'fourteen', 'ten は10、four は4。10ひく4は6なので six です。', 0, 1),
('eigo_lv1_028', 1, 'eigo', '英語の three はいくつ？', '3', '2', '4', '8', '13', '30', 'three は3です。13は thirteen、30は thirty です。', 0, 1),
('eigo_lv1_029', 1, 'eigo', '数の「1」は英語でどれ？', 'one', 'two', 'ten', 'nine', 'eleven', 'zero', '1は one（ワン）です。ten は10、eleven は11です。', 0, 1),
('eigo_lv1_030', 1, 'eigo', '数の「4」は英語でどれ？', 'four', 'five', 'two', 'forty', 'fourteen', 'nine', '4は four です。forty は40、fourteen は14です。', 0, 1),
('eigo_lv1_031', 1, 'eigo', '「赤」は英語でどれ？', 'red', 'blue', 'yellow', 'green', 'pink', 'black', '赤は red（レッド）です。', 0, 1),
('eigo_lv1_032', 1, 'eigo', '英語の blue は何色？', '青', '赤', '黄色', '緑', '白', '黒', 'blue は青。晴れた空や海の色です。', 0, 1),
('eigo_lv1_033', 1, 'eigo', '食べごろのバナナの皮の色を、英語で言うとどれ？', 'yellow', 'red', 'green', 'purple', 'white', 'black', '食べごろのバナナは黄色なので yellow（イエロー）です。', 0, 1),
('eigo_lv1_034', 1, 'eigo', '英語の green は何色？', '緑', '黄色', '茶色', 'むらさき', 'はい色', '赤', 'green は緑。木の葉や草の色です。', 0, 1),
('eigo_lv1_035', 1, 'eigo', '雪の色を英語で言うとどれ？', 'white', 'black', 'blue', 'gray', 'pink', 'brown', '白は white（ホワイト）。雪や牛乳の色です。', 0, 1),
('eigo_lv1_036', 1, 'eigo', '英語の black は何色？', '黒', '白', '赤', '茶色', 'はい色', '青', 'black は黒。夜の空やカラスの色です。', 0, 1),
('eigo_lv1_037', 1, 'eigo', '「むらさき色」は英語でどれ？', 'purple', 'pink', 'brown', 'gray', 'orange', 'silver', 'むらさきは purple（パープル）です。ぶどうやナスのような色です。', 0, 1),
('eigo_lv1_038', 1, 'eigo', '英語の brown は何色？', '茶色', '黒', 'はい色', 'むらさき', '黄色', '赤', 'brown は茶色。チョコレートや木のみきの色です。', 0, 1),
('eigo_lv1_039', 1, 'eigo', '「はい色（ねずみ色）」は英語でどれ？', 'gray', 'green', 'brown', 'silver', 'black', 'white', 'はい色は gray（グレー）です。silver は銀色です。', 0, 1),
('eigo_lv1_040', 1, 'eigo', '「金色」は英語でどれ？', 'gold', 'silver', 'yellow', 'orange', 'white', 'brown', '金色は gold（ゴールド）。銀色は silver（シルバー）です。', 0, 1),
('eigo_lv1_041', 1, 'eigo', '赤と白の絵の具をまぜてできる色は、英語で何という？', 'pink', 'purple', 'orange', 'brown', 'gray', 'yellow', '赤と白をまぜるとピンク色になります。ピンクは英語で pink です。', 0, 1),
('eigo_lv1_042', 1, 'eigo', '「イヌ」は英語でどれ？', 'dog', 'cat', 'pig', 'bear', 'fox', 'cow', 'イヌは dog（ドッグ）です。子イヌは puppy とも言います。', 0, 1),
('eigo_lv1_043', 1, 'eigo', '英語の cat はどの動物？', 'ネコ', 'イヌ', 'ネズミ', 'ウサギ', 'キツネ', 'ブタ', 'cat はネコです。子ネコは kitten とも言います。', 0, 1),
('eigo_lv1_044', 1, 'eigo', '「ウサギ」は英語でどれ？', 'rabbit', 'monkey', 'mouse', 'horse', 'sheep', 'turtle', 'ウサギは rabbit（ラビット）。小さい子どもは bunny とよぶこともあります。', 0, 1),
('eigo_lv1_045', 1, 'eigo', '英語の elephant はどの動物？', 'ゾウ', 'キリン', 'カバ', 'サイ', 'ライオン', 'クマ', 'elephant はゾウ。長い鼻と大きな耳をもつ動物です。', 0, 1),
('eigo_lv1_046', 1, 'eigo', '英語の tiger はどの動物？', 'トラ', 'ライオン', 'ヒョウ', 'チーター', 'オオカミ', 'クマ', 'tiger はトラ。黒いしまもようが目印の、大きなネコのなかまです。', 0, 1),
('eigo_lv1_047', 1, 'eigo', '「サル」は英語でどれ？', 'monkey', 'mouse', 'donkey', 'bear', 'rabbit', 'sheep', 'サルは monkey（モンキー）です。donkey はロバで、つづりがにていますが別の動物です。', 0, 1),
('eigo_lv1_048', 1, 'eigo', '「クマ」は英語でどれ？', 'bear', 'bird', 'deer', 'lion', 'wolf', 'goat', 'クマは bear（ベア）です。ぬいぐるみのテディベアの bear もクマのことです。', 0, 1),
('eigo_lv1_049', 1, 'eigo', '英語の horse はどの動物？', 'ウマ', 'ウシ', 'シカ', 'ロバ', 'ヤギ', 'ヒツジ', 'horse はウマ。速く走れる動物で、人を乗せて走ることもできます。', 0, 1),
('eigo_lv1_050', 1, 'eigo', '「ウシ」は英語でどれ？', 'cow', 'pig', 'horse', 'sheep', 'goat', 'dog', 'ウシは cow（カウ）です。モーと鳴く動物ですね。', 0, 1),
('eigo_lv1_051', 1, 'eigo', '英語の pig はどの動物？', 'ブタ', 'イヌ', 'ウシ', 'ウマ', 'ヒツジ', 'カバ', 'pig はブタです。子ブタは piglet と言います。', 0, 1),
('eigo_lv1_052', 1, 'eigo', '「ヒツジ」は英語でどれ？', 'sheep', 'goat', 'horse', 'cow', 'pig', 'deer', 'ヒツジは sheep（シープ）。goat はヤギなので、まちがえないようにしましょう。', 0, 1),
('eigo_lv1_053', 1, 'eigo', '英語の frog はどの動物？', 'カエル', 'カメ', 'トカゲ', 'ヘビ', 'カニ', 'メダカ', 'frog はカエルです。ケロケロ鳴いて、ぴょんととびはねます。', 0, 1),
('eigo_lv1_054', 1, 'eigo', '次の英語のうち、つばさで空を飛ぶ動物はどれ？', 'bird', 'dog', 'pig', 'cow', 'horse', 'sheep', 'bird は「鳥」。つばさを使って空を飛びます。', 0, 1),
('eigo_lv1_055', 1, 'eigo', '「魚」は英語でどれ？', 'fish', 'bird', 'frog', 'snake', 'duck', 'dish', '魚は fish（フィッシュ）です。dish は「お皿」なので注意しましょう。', 0, 1),
('eigo_lv1_056', 1, 'eigo', '英語の snake はどの動物？', 'ヘビ', 'カメ', 'トカゲ', 'ワニ', 'カエル', 'ミミズ', 'snake はヘビです。足がなく、体をくねらせて進みます。', 0, 1),
('eigo_lv1_057', 1, 'eigo', '「ネズミ」は英語でどれ？', 'mouse', 'rabbit', 'monkey', 'horse', 'cat', 'squirrel', 'ネズミは mouse（マウス）です。パソコンのマウスも同じ mouse です。', 0, 1),
('eigo_lv1_058', 1, 'eigo', '英語の butterfly はどの生き物？', 'チョウ', 'ハチ', 'トンボ', 'アリ', 'クモ', 'カブトムシ', 'butterfly はチョウです。水泳のバタフライと同じことばです。', 0, 1),
('eigo_lv1_059', 1, 'eigo', '英語でネコの鳴き声を表すことばはどれ？', 'meow', 'woof', 'moo', 'oink', 'quack', 'baa', 'ネコの鳴き声は英語で meow（ミャウ）。woof はイヌ、moo はウシの鳴き声です。', 0, 1),
('eigo_lv1_060', 1, 'eigo', '「りんご」は英語でどれ？', 'apple', 'orange', 'lemon', 'peach', 'grape', 'melon', 'りんごは apple（アップル）です。', 0, 1),
('eigo_lv1_061', 1, 'eigo', '英語の strawberry はどのくだもの？', 'いちご', 'さくらんぼ', 'ぶどう', 'もも', 'すいか', 'みかん', 'strawberry はいちごです。', 0, 1),
('eigo_lv1_062', 1, 'eigo', '「ぶどう」は英語でどれ？', 'grape', 'peach', 'pear', 'cherry', 'lemon', 'plum', 'ぶどうは grape。ふさになった実をまとめて grapes とも言います。', 0, 1),
('eigo_lv1_063', 1, 'eigo', '英語の peach はどのくだもの？', 'もも', 'なし', 'かき', 'りんご', 'びわ', 'ぶどう', 'peach はもも。うすいピンク色のあまいくだものです。', 0, 1),
